/*
 * ============================================================
 * PHASE 1 - LEGACY TOOL RESET GATE
 * ============================================================
 *
 * The tools' original drawing implementations were temporarily
 * removed ahead of the LaTeX tool library migration. The gate is
 * now OPEN: Statics (and every other category) creates real,
 * editable objects again, and their TikZ source is generated by
 * the source writers.
 *
 * This module is still the ONE statement of the state. Every
 * arming entry point (activateTool, activateGlobalTool, the
 * Statics analysis arming, the arc/polygon mode menus) and the
 * canvas creation pipelines read it, so the switch can be closed
 * again for a migration test without re-touching every call site
 * and no per-site rule can drift.
 *
 * The remaining placeholder entry points that bypassed this gate
 * (the analysis tools and the coordinate-system menu) have been
 * implemented directly; they no longer report a placeholder.
 */

export const LEGACY_TOOLS_RESET = false;

/*
 * The tools that are NOT part of the reset. Select is the
 * resting state of the editor and Pan is navigation; both
 * keep working exactly as before.
 */
const NON_RESET_TOOLS = [
    "select",
    "pan",

    /* Geometry tools being reintroduced in the LaTeX tool migration. */
    "point",
    "line",
    "triangle",
    "rectangle",
    "circle",
    "arc",
    "reference-arc",
    "polygon",
    "freeform-polygon",

    /* Construction tool (menu) and the concrete tool id it arms. */
    "coordinate-system",
    "coordinate-system-2d"
];

/*
 * Whether a tool id is covered by the reset - that is, whether
 * activating it must be a placeholder rather than its legacy
 * drawing operation.
 */
export function isLegacyResetTool(toolId) {
    if (!LEGACY_TOOLS_RESET) {
        return false;
    }

    return Boolean(toolId) && !NON_RESET_TOOLS.includes(toolId);
}

/*
 * The status message a reset tool shows when activated.
 */
export function legacyPlaceholderMessage() {
    return "Tool placeholder - drawing implementation removed for the LaTeX tool library migration";
}

